package vibe

import (
	"os"
	"path/filepath"
	"strings"

	"github.com/0xdeafcafe/rush/internal/agent"
)

// Vibe ends its commits with a "Generated by Mistral Vibe." line and a
// Co-Authored-By trailer unless its config.toml says
// include_commit_signature = false.
const signatureKey = "include_commit_signature"

// Attribution is whether p's Vibe credits itself.
func (Adapter) Attribution(p agent.Profile) (on, set bool) {
	b, err := os.ReadFile(filepath.Join(p.Dir, "config.toml"))
	if err != nil {
		return false, false
	}
	_, v, ok := topKey(string(b), signatureKey)
	return v == "true", ok
}

// SetAttribution says whether p's Vibe credits itself. Only its one line
// changes: the rest of config.toml, comments and all, stays as it is.
func (Adapter) SetAttribution(p agent.Profile, on bool) error {
	path := filepath.Join(p.Dir, "config.toml")
	b, err := os.ReadFile(path)
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	line := signatureKey + " = false"
	if on {
		line = signatureKey + " = true"
	}
	text := string(b)
	if i, _, ok := topKey(text, signatureKey); ok {
		lines := strings.Split(text, "\n")
		lines[i] = line
		text = strings.Join(lines, "\n")
	} else {
		text = line + "\n" + text // a top-level key goes before any table
	}
	if err := os.MkdirAll(p.Dir, 0o700); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, []byte(text), 0o600); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// topKey finds key among a TOML file's top-level keys, those before its
// first table: its line, and its value as written.
func topKey(text, key string) (line int, value string, ok bool) {
	for i, l := range strings.Split(text, "\n") {
		t := strings.TrimSpace(l)
		if strings.HasPrefix(t, "[") {
			break
		}
		k, v, found := strings.Cut(t, "=")
		if found && strings.TrimSpace(k) == key {
			v, _, _ = strings.Cut(v, "#")
			return i, strings.TrimSpace(v), true
		}
	}
	return 0, "", false
}

var _ agent.Attributor = Adapter{}
